import{_ as i,o as s,c as l,a2 as a}from"./chunks/framework.CnH-Xjyd.js";const M=JSON.parse('{"title":"本次考核: 基础 - HTML","description":"","frontmatter":{},"headers":[],"relativePath":"assessment/basic/html.md","filePath":"assessment/basic/html.md"}'),t={name:"assessment/basic/html.md"};function o(c,e,d,n,p,r){return s(),l("div",null,[...e[0]||(e[0]=[a(`<h1 id="本次考核-基础-html" tabindex="-1">本次考核: 基础 - HTML <a class="header-anchor" href="#本次考核-基础-html" aria-label="Permalink to &quot;本次考核: 基础 - HTML&quot;">​</a></h1><h2 id="dom-和-bom" tabindex="-1">DOM 和 BOM <a class="header-anchor" href="#dom-和-bom" aria-label="Permalink to &quot;DOM 和 BOM&quot;">​</a></h2><ol><li>什么是 DOM?</li></ol><p>DOM (Document Object Model, 文档对象模型)</p><p>DOM 是浏览器把 HTML 文档解析出来的文档对象模型, 用来操作页面文档</p><ul><li>DOM 的核心对象是 <code>document</code>, 它是整个页面文档的入口</li><li>DOM 将 HTML 文档抽象成树形结构 (DOM 树), 每一个标签, 文本, 注释都是树上的节点</li><li>JS 通过 DOM API 实现对页面的操作: 获取 / 修改元素, 修改内容, 修改样式, 增删节点, 绑定事件等</li><li>DOM 属于文档层面, 只和页面文档相关</li></ul><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 获取页面元素</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">document.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getElementById</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;app&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 修改页面内容</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">element.innerHTML </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;hello&#39;</span></span></code></pre></div><ol start="2"><li>什么是 BOM?</li></ol><p>BOM (Browser Object Model, 浏览器对象模型)</p><p>BOM 是浏览器提供的浏览器对象模型, 用来操作浏览器窗口本身</p><ul><li>BOM 的核心对象是 <code>window</code> 浏览器的全局对象, 所有全局变量都挂载在它上面</li><li>BOM 提供和页面文档无关的浏览器能力: 浏览器窗口, 地址栏, 历史记录, 定时器, 弹窗, 浏览器信息等</li><li>常用 BOM 对象: <code>location</code>, <code>history</code>, <code>navigator</code>, <code>screen</code>, 定时器 <code>setTimeout / setInterval</code></li><li>DOM 其实是 BOM 的一部分: <code>window.document</code> 就是 DOM 的入口</li></ul><ol start="3"><li>总结DOM 和 BOM 的区别是什么?</li></ol><p>DOM 管页面内容, BOM 管浏览器窗口</p><h2 id="浏览器执行过程" tabindex="-1">浏览器执行过程 <a class="header-anchor" href="#浏览器执行过程" aria-label="Permalink to &quot;浏览器执行过程&quot;">​</a></h2><p>说一下浏览器输入 URL 到页面完整显示全过程?</p><p>简述: 整体分为 7 大阶段: DNS 解析 → TCP 连接 → HTTP 请求 → 服务器响应 → 浏览器解析渲染 → 页面布局绘制合成 → 断开连接</p><p>(待补充)</p><h2 id="script-标签位置" tabindex="-1">Script 标签位置 <a class="header-anchor" href="#script-标签位置" aria-label="Permalink to &quot;Script 标签位置&quot;">​</a></h2><p><code>&lt;script&gt;</code> 为什么建议放在 <code>&lt;body&gt;</code> 的底部?</p><p>浏览器解析 HTML 是从上到下串行解析的. 当解析遇到 <code>&lt;script&gt;</code> 时</p><ul><li>如果是外部脚本, 会暂停 HTML DOM 的解析, 去下载 JS 文件, 下载完成后还要执行 JS 代码</li><li>JS 执行时会阻塞 DOM 树构建, 因为 JavaScript 可以修改 DOM, 修改 CSSOM, 浏览器不能一边构建 DOM, 一边让 JS 修改它, 所以必须暂停解析</li></ul><p>如果把 <code>&lt;script&gt;</code> 放在 <code>&lt;head&gt;</code> 里</p><ul><li>HTML 还没解析到页面 DOM 元素, DOM 树不完整, JS 如果操作页面元素, 会获取不到元素, 报错</li><li>JS 的下载和执行会阻塞后续 HTML 解析, 页面白屏时间变长, 用户体验差</li></ul><p>放在 <code>&lt;/body&gt;</code> 之前 (Body 底部)</p><ul><li>此时 HTML 已经解析完毕, DOM 树构建完成, JS 可以正常访问页面上所有 DOM 节点</li><li>JS 的下载执行不会阻塞页面 HTML 的解析渲染, 减少白屏时间, 页面能更快展示内容</li></ul><p>补充</p><p>现在不一定要放底部, 可以使用属性解决阻塞问题</p><ul><li>使用 defer 属性 <code>&lt;script defer src=&quot;...&quot;&gt;</code>: 脚本后台异步下载, 等到整个 HTML 解析完成之后, 再按顺序执行脚本. 不阻塞 DOM 解析</li><li>使用 async 属性 <code>&lt;script async src=&quot;...&quot;&gt;</code>: 脚本后台异步下载, 下载完成立刻执行, 执行顺序不能保证, 适合不依赖 DOM, 不互相依赖的脚本</li></ul><p>区别: <code>defer</code> 解析完再执行, 保序, 等价于放到 body 底部, <code>async</code> 下载完就执行, 顺序不可控</p>`,29)])])}const k=i(t,[["render",o]]);export{M as __pageData,k as default};
